     1→import * as vscode from 'vscode';
     2→import { TabInfo, ContextSnapshot, TurnSnapshot, SessionSummary } from './types';
     3→import { TabRelevanceScorer } from './tabRelevanceScorer';
     4→import { TokenBudgetEstimator } from './tokenBudgetEstimator';
     5→import { TokenizerService } from './tokenizerService';
     6→import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel } from './modelProfiles';
     7→import { SessionLogger } from './sessionLogger';
     8→
     9→const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
    10→const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
    11→const SESSION_KEY = 'tokalator.lastSession';
    12→
    13→/**
    14→ * Core engine that tracks all editor state and produces real-time ContextSnapshots.
    15→ *
    16→ * Subscribes to:
    17→ *  - Active editor changes
    18→ *  - Tab open/close events
    19→ *  - Text document changes
    20→ *  - Diagnostics changes
    21→ *
    22→ * Emits:
    23→ *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
    24→ */
    25→export class ContextMonitor implements vscode.Disposable {
    26→
    27→  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
    28→  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;
    29→
    30→  private readonly scorer = new TabRelevanceScorer();
    31→  private readonly tokenizer = new TokenizerService();
    32→  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);
    33→
    34→  private pinnedFiles = new Set<string>();
    35→  private chatTurnCount = 0;
    36→  private turnHistory: TurnSnapshot[] = [];
    37→  private lastEditTimestamps = new Map<string, number>();
    38→  private disposables: vscode.Disposable[] = [];
    39→  private refreshTimer: ReturnType<typeof setInterval> | undefined;
    40→
    41→  private latestSnapshot: ContextSnapshot | null = null;
    42→  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
    43→  private isRefreshing = false;
    44→  private pendingRefresh = false;
    45→
    46→  private activeModel: ModelProfile;
    47→  private workspaceFileTokens = 0;
    48→  private workspaceFileCount = 0;
    49→
    50→  // Session tracking
    51→  private peakTokens = 0;
    52→  private peakPercent = 0;
    53→  private fileEditCounts = new Map<string, number>();
    54→
    55→  // Opt-in session logger for research studies
    56→  private sessionLogger: SessionLogger | null = null;
    57→
    58→  constructor(private readonly workspaceState?: vscode.Memento) {
    59→    // Load persisted pinned files (normalize URIs for consistent matching)
    60→    if (workspaceState) {
    61→      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
    62→      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
    63→    }
    64→
    65→    // Load persisted model selection
    66→    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
    67→    this.activeModel = getModel(savedModelId);
    68→    this.estimator.setProvider(this.activeModel.provider);
    69→
    70→    // Scan workspace files on startup
    71→    this.scanWorkspaceFiles();
    72→
    73→    // Debounced refresh to avoid perf issues from rapid event firing
    74→    const debouncedRefresh = () => {
    75→      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
    76→      this.debounceTimer = setTimeout(() => this.refresh(), 300);
    77→    };
    78→
    79→    // Subscribe to VS Code events
    80→    this.disposables.push(
    81→      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
    82→      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
    83→      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
    84→      vscode.workspace.onDidChangeTextDocument(e => {
    85→        const uri = e.document.uri.toString();
    86→        this.lastEditTimestamps.set(uri, Date.now());
    87→        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
    88→        debouncedRefresh();
    89→      }),
    90→      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
    91→      // Clean up caches when documents close (memory leak fix)
    92→      vscode.workspace.onDidCloseTextDocument(doc => {
    93→        const uri = doc.uri.toString();
    94→        this.lastEditTimestamps.delete(uri);
    95→        this.estimator.clearCacheFor(uri);
    96→        debouncedRefresh();
    97→      }),
    98→      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
    99→      // Sync model when settings change (skip if already on that model to avoid loop)
   100→      vscode.workspace.onDidChangeConfiguration(e => {
   101→        if (e.affectsConfiguration('tokalator.model')) {
   102→          const cfg = vscode.workspace.getConfiguration('tokalator');
   103→          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
   104→          if (modelId !== this.activeModel.id) {
   105→            this.setModel(modelId);
   106→          }
   107→        }
   108→      }),
   109→    );
   110→
   111→    // Periodic refresh for time-based scoring (recency decay)
   112→    const config = vscode.workspace.getConfiguration('tokalator');
   113→    const interval = config.get<number>('autoRefreshInterval', 2000);
   114→    this.refreshTimer = setInterval(() => this.refresh(), interval);
   115→
   116→    // Opt-in session logging for research studies
   117→    if (config.get<boolean>('enableSessionLogging', false)) {
   118→      this.sessionLogger = new SessionLogger();
   119→      this.sessionLogger.startSession(this.activeModel.id);
   120→    }
   121→
   122→    // Initial snapshot
   123→    this.refresh();
   124→  }
   125→
   126→  /**
   127→   * Build a fresh snapshot and emit it.
   128→   */
   129→  async refresh(): Promise<void> {
   130→    if (this.isRefreshing) {
   131→      // Queue one pending refresh so the final state after rapid switching is captured
   132→      this.pendingRefresh = true;
   133→      return;
   134→    }
   135→    this.isRefreshing = true;
   136→    this.pendingRefresh = false;
   137→    try {
   138→      const snapshot = await this.buildSnapshot();
   139→      this.latestSnapshot = snapshot;
   140→      this._onDidUpdateSnapshot.fire(snapshot);
   141→
   142→      // Log snapshot to session logger if enabled
   143→      if (this.sessionLogger) {
   144→        this.sessionLogger.logSnapshot({
   145→          tabCount: snapshot.tabs.length,
   146→          totalTokens: snapshot.totalEstimatedTokens,
   147→          budgetPercent: snapshot.percentUsed,
   148→          budgetLevel: snapshot.budgetLevel,
   149→          distractorCount: snapshot.tabs.filter(t => t.relevanceScore < 0.3).length,
   150→          relevanceScores: snapshot.tabs.map(t => ({ languageId: t.languageId, score: t.relevanceScore })),
   151→        });
   152→      }
   153→    } finally {
   154→      this.isRefreshing = false;
   155→      // If events arrived while we were refreshing, run one more pass
   156→      if (this.pendingRefresh) {
   157→        this.pendingRefresh = false;
   158→        void this.refresh();
   159→      }
   160→    }
   161→  }
   162→
   163→  /**
   164→   * Get the most recent snapshot without triggering a refresh.
   165→   */
   166→  getLatestSnapshot(): ContextSnapshot | null {
   167→    return this.latestSnapshot;
   168→  }
   169→
   170→  /**
   171→   * Normalize a URI string for consistent Set matching.
   172→   */
   173→  private normalizeUri(uri: string): string {
   174→    try {
   175→      return vscode.Uri.parse(uri).toString();
   176→    } catch {
   177→      return uri;
   178→    }
   179→  }
   180→
   181→  /**
   182→   * Pin a file URI so it's always scored as maximum relevance.
   183→   */
   184→  pinFile(uri: string): void {
   185→    this.pinnedFiles.add(this.normalizeUri(uri));
   186→    this.persistPins();
   187→    this.refresh();
   188→  }
   189→
   190→  /**
   191→   * Unpin a file.
   192→   */
   193→  unpinFile(uri: string): void {
   194→    this.pinnedFiles.delete(this.normalizeUri(uri));
   195→    this.persistPins();
   196→    this.refresh();
   197→  }
   198→
   199→  /**
   200→   * Clear all pins.
   201→   */
   202→  clearPins(): void {
   203→    this.pinnedFiles.clear();
   204→    this.persistPins();
   205→    this.refresh();
   206→  }
   207→
   208→  /**
   209→   * Persist pinned files to workspace state.
   210→   */
   211→  private persistPins(): void {
   212→    if (this.workspaceState) {
   213→      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
   214→    }
   215→  }
   216→
   217→  /**
   218→   * Increment the conversation turn counter and capture a turn snapshot.
   219→   * Only call this for actual user interactions, not status checks.
   220→   */
   221→  async incrementChatTurns(): Promise<void> {
   222→    this.chatTurnCount++;
   223→
   224→    // Capture a turn snapshot for compaction tracking
   225→    const snapshot = this.latestSnapshot;
   226→    if (snapshot) {
   227→      const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
   228→      const overheadTokens = snapshot.totalEstimatedTokens - fileTokens;
   229→      this.turnHistory.push({
   230→        turn: this.chatTurnCount,
   231→        timestamp: Date.now(),
   232→        inputTokens: snapshot.totalEstimatedTokens,
   233→        outputReserved: this.activeModel.maxOutput,
   234→        fileTokens,
   235→        overheadTokens,
   236→        tabCount: snapshot.tabs.length,
   237→        pinnedCount: this.pinnedFiles.size,
   238→      });
   239→    }
   240→
   241→    this.refresh();
   242→  }
   243→
   244→  /**
   245→   * Estimate the token cost of the *next* chat turn before sending.
   246→   * This gives users a preview of what will be consumed.
   247→   */
   248→  async previewNextTurn(): Promise<{
   249→    currentInput: number;
   250→    nextTurnEstimate: number;
   251→    conversationGrowth: number;
   252→    outputReserved: number;
   253→    remainingCapacity: number;
   254→    percentAfterTurn: number;
   255→    windowCapacity: number;
   256→    warning: string | null;
   257→  }> {
   258→    await this.refresh();
   259→    const snapshot = this.latestSnapshot;
   260→    if (!snapshot) {
   261→      return {
   262→        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
   263→        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
   264→        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
   265→      };
   266→    }
   267→
   268→    // Each turn adds ~800 tokens (user message + assistant response)
   269→    const perTurnCost = 800;
   270→    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
   271→    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
   272→    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);
   273→
   274→    let warning: string | null = null;
   275→    if (nextPercent >= 90) {
   276→      warning = 'Next turn will push you past 90% — high risk of context overflow';
   277→    } else if (nextPercent >= 75) {
   278→      warning = 'Approaching context limit — consider closing tabs or resetting';
   279→    }
   280→
   281→    // Check if next turn crosses the rot threshold
   282→    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
   283→      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
   284→      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
   285→    }
   286→
   287→    return {
   288→      currentInput: snapshot.totalEstimatedTokens,
   289→      nextTurnEstimate: nextTurnInput,
   290→      conversationGrowth: perTurnCost,
   291→      outputReserved: this.activeModel.maxOutput,
   292→      remainingCapacity: remaining,
   293→      percentAfterTurn: nextPercent,
   294→      windowCapacity: snapshot.windowCapacity,
   295→      warning,
   296→    };
   297→  }
   298→
   299→  /**
   300→   * Reset conversation turn counter and clear turn history.
   301→   */
   302→  resetChatTurns(): void {
   303→    this.chatTurnCount = 0;
   304→    this.turnHistory = [];
   305→    this.refresh();
   306→  }
   307→
   308→  /**
   309→   * Get current chat turn count.
   310→   */
   311→  getChatTurnCount(): number {
   312→    return this.chatTurnCount;
   313→  }
   314→
   315→  /**
   316→   * Get the per-turn snapshot history for compaction analysis.
   317→   */
   318→  getTurnHistory(): TurnSnapshot[] {
   319→    return [...this.turnHistory];
   320→  }
   321→
   322→  /**
   323→   * Close tabs below relevance threshold.
   324→   * Returns the list of closed tab labels.
   325→   */
   326→  async optimizeTabs(): Promise<string[]> {
   327→    const config = vscode.workspace.getConfiguration('tokalator');
   328→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   329→
   330→    const snapshot = await this.buildSnapshot();
   331→    const toClose = snapshot.tabs.filter(
   332→      t => t.relevanceScore < threshold && !t.isActive && !t.isPinned
   333→    );
   334→
   335→    const closed: string[] = [];
   336→    for (const tab of toClose) {
   337→      const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
   338→      const vsTab = allTabs.find(t => {
   339→        if (t.input instanceof vscode.TabInputText) {
   340→          return t.input.uri.toString() === tab.uri.toString();
   341→        }
   342→        return false;
   343→      });
   344→      if (vsTab) {
   345→        await vscode.window.tabGroups.close(vsTab);
   346→        closed.push(tab.label);
   347→      }
   348→    }
   349→
   350→    // Log optimize action to session logger if enabled
   351→    if (this.sessionLogger && closed.length > 0) {
   352→      this.sessionLogger.logOptimize(closed.length, threshold);
   353→    }
   354→
   355→    return closed;
   356→  }
   357→
   358→  /**
   359→   * Build the full context snapshot.
   360→   */
   361→  private async buildSnapshot(): Promise<ContextSnapshot> {
   362→    const config = vscode.workspace.getConfiguration('tokalator');
   363→    // Use windowSize setting as override only when it differs from the default (1,000,000)
   364→    const configWindowSize = config.get<number>('windowSize', 1000000);
   365→    const windowCapacity = configWindowSize !== 1000000 ? configWindowSize : this.activeModel.contextWindow;
   366→    const rotWarning = this.activeModel.rotThreshold;
   367→
   368→    // 1. Gather all open tabs
   369→    let tabs = this.gatherTabs();
   370→
   371→    // 2. Estimate tokens for each tab
   372→    tabs = await this.estimator.estimateAllTabs(tabs);
   373→
   374→    // 3. Score relevance
   375→    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
   376→
   377→    // 4. Sort by relevance (highest first)
   378→    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
   379→
   380→    // 5. Gather diagnostics summary
   381→    const diagnosticsSummary = this.gatherDiagnosticsSummary();
   382→
   383→    // 6. Count instruction files in workspace
   384→    const instructionFiles = await this.countInstructionFiles();
   385→
   386→    // 7. Compute budget
   387→    const budget = this.estimator.computeBudget(
   388→      tabs,
   389→      this.chatTurnCount,
   390→      instructionFiles,
   391→      windowCapacity
   392→    );
   393→
   394→    // Track peak usage for session summary
   395→    if (budget.used > this.peakTokens) {
   396→      this.peakTokens = budget.used;
   397→      this.peakPercent = budget.percent;
   398→    }
   399→
   400→    // 8. Determine budget level (simplified from percentage)
   401→    let budgetLevel: 'low' | 'medium' | 'high';
   402→    if (budget.percent > 85) {
   403→      budgetLevel = 'high';
   404→    } else if (budget.percent > 60) {
   405→      budgetLevel = 'medium';
   406→    } else {
   407→      budgetLevel = 'low';
   408→    }
   409→
   410→    // 9. Determine health and reasons
   411→    const healthReasons: string[] = [];
   412→    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
   413→
   414→    if (budgetLevel === 'high') {
   415→      contextHealth = 'critical';
   416→      healthReasons.push('Token budget is high — context overflow risk');
   417→    } else if (budgetLevel === 'medium') {
   418→      contextHealth = 'warning';
   419→      healthReasons.push('Token budget is medium — consider closing unused tabs');
   420→    }
   421→
   422→    if (this.chatTurnCount >= rotWarning) {
   423→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   424→      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
   425→    }
   426→
   427→    const distractors = tabs.filter(t => {
   428→      const threshold = config.get<number>('relevanceThreshold', 0.3);
   429→      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
   430→    });
   431→    if (distractors.length > 3) {
   432→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   433→      healthReasons.push(`${distractors.length} low-relevance tabs open`);
   434→    }
   435→
   436→    if (healthReasons.length === 0) {
   437→      healthReasons.push('Token budget looks good');
   438→    }
   439→
   440→    const activeFile = tabs.find(t => t.isActive) || null;
   441→
   442→    return {
   443→      timestamp: Date.now(),
   444→      activeFile,
   445→      tabs,
   446→      pinnedFiles: this.pinnedFiles,
   447→      totalEstimatedTokens: budget.used,
   448→      windowCapacity,
   449→      usagePercent: budget.percent,
   450→      budgetLevel,
   451→      diagnosticsSummary,
   452→      chatTurnCount: this.chatTurnCount,
   453→      contextHealth,
   454→      healthReasons,
   455→      modelId: this.activeModel.id,
   456→      modelLabel: this.activeModel.label,
   457→      workspaceFileCount: this.workspaceFileCount,
   458→      workspaceFileTokens: this.workspaceFileTokens,
   459→      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
   460→      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
   461→      turnHistory: [...this.turnHistory],
   462→      budgetBreakdown: budget.breakdown,
   463→    };
   464→  }
   465→
   466→  /**
   467→   * Gather TabInfo from all open tab groups.
   468→   */
   469→  private gatherTabs(): TabInfo[] {
   470→    const tabs: TabInfo[] = [];
   471→    const seenUris = new Set<string>();
   472→    const workspaceFolders = vscode.workspace.workspaceFolders || [];
   473→
   474→    for (const group of vscode.window.tabGroups.all) {
   475→      for (const tab of group.tabs) {
   476→        if (!(tab.input instanceof vscode.TabInputText)) { continue; }
   477→
   478→        const uri = tab.input.uri;
   479→        const uriKey = uri.toString();
   480→
   481→        // Skip duplicate URIs (same file open in split panes)
   482→        if (seenUris.has(uriKey)) { continue; }
   483→        seenUris.add(uriKey);
   484→
   485→        const fsPath = uri.fsPath;
   486→
   487→        // Find the matching workspace folder for correct relative path in multi-root workspaces
   488→        const matchingFolder = workspaceFolders.find(f => fsPath.startsWith(f.uri.fsPath));
   489→        const relativePath = matchingFolder
   490→          ? fsPath.replace(matchingFolder.uri.fsPath, '').replace(/^[/\\]/, '')
   491→          : fsPath;
   492→
   493→        // Get language ID from open documents
   494→        const openDoc = vscode.workspace.textDocuments.find(
   495→          d => d.uri.toString() === uri.toString()
   496→        );
   497→        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);
   498→
   499→        // Get diagnostics for this file
   500→        const diagnostics = vscode.languages.getDiagnostics(uri);
   501→        const diagnosticCount = diagnostics.length;
   502→
   503→        // Get last edit timestamp
   504→        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;
   505→
   506→        tabs.push({
   507→          uri,
   508→          label: tab.label,
   509→          languageId,
   510→          relativePath,
   511→          estimatedTokens: 0,   // filled later by estimator
   512→          relevanceScore: 0,     // filled later by scorer
   513→          relevanceReason: '',
   514→          isActive: tab.isActive,
   515→          isDirty: tab.isDirty,
   516→          isPinned: this.pinnedFiles.has(uri.toString()),
   517→          diagnosticCount,
   518→          lastEditTimestamp: lastEdit,
   519→        });
   520→      }
   521→    }
   522→
   523→    return tabs;
   524→  }
   525→
   526→  /**
   527→   * Aggregate diagnostics across all open files.
   528→   */
   529→  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
   530→    const allDiags = vscode.languages.getDiagnostics();
   531→    let errors = 0, warnings = 0, info = 0;
   532→
   533→    for (const [, diags] of allDiags) {
   534→      for (const d of diags) {
   535→        switch (d.severity) {
   536→          case vscode.DiagnosticSeverity.Error: errors++; break;
   537→          case vscode.DiagnosticSeverity.Warning: warnings++; break;
   538→          default: info++; break;
   539→        }
   540→      }
   541→    }
   542→
   543→    return { errors, warnings, info };
   544→  }
   545→
   546→  /**
   547→   * Count .instructions.md files in the workspace (they consume context budget).
   548→   */
   549→  private async countInstructionFiles(): Promise<number> {
   550→    try {
   551→      const exclude = '**/node_modules/**';
   552→      const [instrFiles, copilotInstr, claudeMd, agentsMd, cursorRules] = await Promise.all([
   553→        vscode.workspace.findFiles('**/*.instructions.md', exclude, 20),
   554→        vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1),
   555→        vscode.workspace.findFiles('**/CLAUDE.md', exclude, 5),
   556→        vscode.workspace.findFiles('**/AGENTS.md', exclude, 5),
   557→        vscode.workspace.findFiles('**/.cursorrules', exclude, 5),
   558→      ]);
   559→      return instrFiles.length + copilotInstr.length + claudeMd.length + agentsMd.length + cursorRules.length;
   560→    } catch {
   561→      return 0;
   562→    }
   563→  }
   564→
   565→  /**
   566→   * Guess language from file extension.
   567→   */
   568→  private guessLanguage(fsPath: string): string {
   569→    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
   570→    const map: Record<string, string> = {
   571→      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
   572→      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
   573→      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
   574→      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
   575→    };
   576→    return map[ext] || ext;
   577→  }
   578→
   579→  /**
   580→   * Set the active model and persist it.
   581→   */
   582→  async setModel(modelId: string): Promise<void> {
   583→    this.activeModel = getModel(modelId);
   584→    this.estimator.setProvider(this.activeModel.provider);
   585→    if (this.workspaceState) {
   586→      this.workspaceState.update(SELECTED_MODEL_KEY, modelId);
   587→    }
   588→    // Sync the VS Code setting so Settings UI / dashboard selector stay in sync
   589→    const cfg = vscode.workspace.getConfiguration('tokalator');
   590→    const currentSetting = cfg.get<string>('model');
   591→    if (currentSetting !== modelId) {
   592→      await cfg.update('model', modelId, vscode.ConfigurationTarget.Global);
   593→    }
   594→    // Rescan workspace with new tokenizer ratios, then refresh dashboard
   595→    await this.scanWorkspaceFiles();
   596→    await this.refresh();
   597→  }
   598→
   599→  /**
   600→   * Get the current active model.
   601→   */
   602→  getActiveModel(): ModelProfile {
   603→    return this.activeModel;
   604→  }
   605→
   606→  /**
   607→   * Get all available models.
   608→   */
   609→  getModels(): ModelProfile[] {
   610→    return MODEL_PROFILES;
   611→  }
   612→
   613→  /**
   614→   * Get the tokenizer service for direct token counting.
   615→   */
   616→  getTokenizer(): TokenizerService {
   617→    return this.tokenizer;
   618→  }
   619→
   620→  /**
   621→   * Scan workspace files to estimate total project token count.
   622→   * This runs once on startup and on workspace change.
   623→   */
   624→  private async scanWorkspaceFiles(): Promise<void> {
   625→    try {
   626→      const files = await vscode.workspace.findFiles(
   627→        '**/*.{ts,tsx,js,jsx,py,go,rs,java,rb,md,json,yml,yaml,css,html,sh,sql,c,cpp,h,cs,swift,kt}',
   628→        '{**/node_modules/**,**/dist/**,**/build/**,**/.next/**,**/vendor/**,**/.git/**}',
   629→        5000
   630→      );
   631→      this.workspaceFileCount = files.length;
   632→
   633→      // Estimate total workspace tokens using provider-specific byte ratios
   634→      let totalBytes = 0;
   635→      for (const uri of files) {
   636→        try {
   637→          const stat = await vscode.workspace.fs.stat(uri);
   638→          totalBytes += stat.size;
   639→        } catch {
   640→          // skip unreadable files
   641→        }
   642→      }
   643→      this.workspaceFileTokens = this.tokenizer.estimateFromBytes(totalBytes, this.activeModel.provider);
   644→    } catch {
   645→      this.workspaceFileCount = 0;
   646→      this.workspaceFileTokens = 0;
   647→    }
   648→  }
   649→
   650→  /**
   651→   * Save a session summary to workspace state for next activation.
   652→   */
   653→  saveSessionSummary(): void {
   654→    const snapshot = this.latestSnapshot;
   655→    if (!snapshot || !this.workspaceState) return;
   656→
   657→    const topFiles = [...this.fileEditCounts.entries()]
   658→      .sort((a, b) => b[1] - a[1])
   659→      .slice(0, 5)
   660→      .map(([uri]) => {
   661→        try {
   662→          return vscode.workspace.asRelativePath(vscode.Uri.parse(uri));
   663→        } catch {
   664→          return uri;
   665→        }
   666→      });
   667→
   668→    const summary: SessionSummary = {
   669→      endedAt: new Date().toISOString(),
   670→      modelId: this.activeModel.id,
   671→      modelLabel: this.activeModel.label,
   672→      totalTurns: this.chatTurnCount,
   673→      peakTokens: this.peakTokens,
   674→      peakPercent: this.peakPercent,
   675→      tabCount: snapshot.tabs.length,
   676→      pinnedCount: this.pinnedFiles.size,
   677→      filesWorkedOn: topFiles,
   678→      budgetLevel: snapshot.budgetLevel,
   679→      healthStatus: snapshot.contextHealth,
   680→    };
   681→
   682→    this.workspaceState.update(SESSION_KEY, summary);
   683→  }
   684→
   685→  /**
   686→   * Get last session summary (if any).
   687→   */
   688→  getLastSession(): SessionSummary | undefined {
   689→    return this.workspaceState?.get<SessionSummary>(SESSION_KEY);
   690→  }
   691→
   692→  dispose(): void {
   693→    this.saveSessionSummary();
   694→    if (this.sessionLogger) { this.sessionLogger.endSession(); }
   695→    if (this.refreshTimer) { clearInterval(this.refreshTimer); }
   696→    if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
   697→    this._onDidUpdateSnapshot.dispose();
   698→    this.tokenizer.dispose();
   699→    this.disposables.forEach(d => d.dispose());
   700→  }
   701→}
