     1→import * as vscode from 'vscode';
     2→import * as fs from 'fs';
     3→import * as path from 'path';
     4→import { ContextSnapshot } from './types';
     5→
     6→/** A single logged event within a session. */
     7→interface SessionEvent {
     8→  timestamp: string;
     9→  type: 'session_start' | 'session_end' | 'snapshot' | 'optimize' | 'command';
    10→  data: Record<string, unknown>;
    11→}
    12→
    13→/** Full session log written to disk. */
    14→interface SessionLog {
    15→  sessionId: string;
    16→  startedAt: string;
    17→  endedAt?: string;
    18→  modelId: string;
    19→  events: SessionEvent[];
    20→}
    21→
    22→/**
    23→ * Opt-in session logger for controlled experiment data collection.
    24→ * Writes anonymized JSON logs to ~/.tokalator/sessions/.
    25→ * No file contents, no file names — only counts, scores, and timestamps.
    26→ */
    27→export class SessionLogger implements vscode.Disposable {
    28→  private log: SessionLog | null = null;
    29→  private logDir: string;
    30→  private enabled = false;
    31→
    32→  constructor() {
    33→    this.logDir = path.join(
    34→      process.env.HOME || process.env.USERPROFILE || '/tmp',
    35→      '.tokalator',
    36→      'sessions'
    37→    );
    38→  }
    39→
    40→  /** Check configuration and enable/disable logging. */
    41→  isEnabled(): boolean {
    42→    const config = vscode.workspace.getConfiguration('tokalator');
    43→    return config.get<boolean>('enableSessionLogging', false);
    44→  }
    45→
    46→  /** Start a new session log. */
    47→  startSession(modelId: string): void {
    48→    if (!this.isEnabled()) { return; }
    49→    this.enabled = true;
    50→
    51→    const sessionId = `session-${Date.now()}`;
    52→    this.log = {
    53→      sessionId,
    54→      startedAt: new Date().toISOString(),
    55→      modelId,
    56→      events: [],
    57→    };
    58→
    59→    this.addEvent('session_start', { modelId });
    60→  }
    61→
    62→  /** Record a context snapshot (anonymized — no file names or contents). */
    63→  logSnapshot(snapshot: ContextSnapshot): void {
    64→    if (!this.enabled || !this.log) { return; }
    65→
    66→    this.addEvent('snapshot', {
    67→      totalEstimatedTokens: snapshot.totalEstimatedTokens,
    68→      windowCapacity: snapshot.windowCapacity,
    69→      usagePercent: snapshot.usagePercent,
    70→      budgetLevel: snapshot.budgetLevel,
    71→      contextHealth: snapshot.contextHealth,
    72→      tabCount: snapshot.tabs.length,
    73→      pinnedCount: snapshot.pinnedFiles.size,
    74→      chatTurnCount: snapshot.chatTurnCount,
    75→      modelId: snapshot.modelId,
    76→      // Per-tab scores only (no names/paths)
    77→      tabScores: snapshot.tabs.map(t => ({
    78→        relevanceScore: t.relevanceScore,
    79→        estimatedTokens: t.estimatedTokens,
    80→        languageId: t.languageId,
    81→        isActive: t.isActive,
    82→        isPinned: t.isPinned,
    83→        diagnosticCount: t.diagnosticCount,
    84→      })),
    85→      budgetBreakdown: snapshot.budgetBreakdown,
    86→    });
    87→  }
    88→
    89→  /** Record an /optimize command execution. */
    90→  logOptimize(tabsBefore: number, tokensBefore: number, tabsClosed: number): void {
    91→    if (!this.enabled || !this.log) { return; }
    92→
    93→    this.addEvent('optimize', {
    94→      tabsBefore,
    95→      tokensBefore,
    96→      tabsClosed,
    97→    });
    98→  }
    99→
   100→  /** Record any chat command invocation. */
   101→  logCommand(command: string): void {
   102→    if (!this.enabled || !this.log) { return; }
   103→
   104→    this.addEvent('command', { command });
   105→  }
   106→
   107→  /** End the session and write the log to disk. */
   108→  endSession(finalSnapshot?: ContextSnapshot): void {
   109→    if (!this.enabled || !this.log) { return; }
   110→
   111→    if (finalSnapshot) {
   112→      this.logSnapshot(finalSnapshot);
   113→    }
   114→
   115→    this.log.endedAt = new Date().toISOString();
   116→    this.addEvent('session_end', {});
   117→
   118→    this.writeToDisk();
   119→    this.log = null;
   120→    this.enabled = false;
   121→  }
   122→
   123→  private addEvent(type: SessionEvent['type'], data: Record<string, unknown>): void {
   124→    if (!this.log) { return; }
   125→    this.log.events.push({
   126→      timestamp: new Date().toISOString(),
   127→      type,
   128→      data,
   129→    });
   130→  }
   131→
   132→  private writeToDisk(): void {
   133→    if (!this.log) { return; }
   134→    try {
   135→      fs.mkdirSync(this.logDir, { recursive: true });
   136→      const filePath = path.join(this.logDir, `${this.log.sessionId}.json`);
   137→      fs.writeFileSync(filePath, JSON.stringify(this.log, null, 2), 'utf-8');
   138→    } catch {
   139→      // Silently fail — logging should never break the extension
   140→    }
   141→  }
   142→
   143→  dispose(): void {
   144→    if (this.enabled && this.log) {
   145→      this.endSession();
   146→    }
   147→  }
   148→}
   149→

