     8→/**
     9→ * Chat participant `@tokalator` for Tokalator.
    10→ *
    11→ * Commands:
    12→ *  /count        — Show current token count and budget level
    13→ *  /optimize     — Close low-relevance tabs
    14→ *  /pin          — Pin a file as always-relevant
    15→ *  /unpin        — Unpin a file
    16→ *  /breakdown    — Show where tokens are going
    17→ *  /instructions — List and estimate tokens for instruction files
    18→ *  /model        — Show or switch the active AI model
    19→ *  /compaction   — Per-turn token growth and compaction recommendations
    20→ *  /reset        — Reset session state (turn counter)
    21→ */
    22→export class ContextChatParticipant implements vscode.Disposable {
    23→
    24→  private participant: vscode.ChatParticipant;
    25→
    26→  constructor(private readonly monitor: ContextMonitor) {
    27→    this.participant = vscode.chat.createChatParticipant(
    28→      'tokalator.tokens',
    29→      this.handleRequest.bind(this),
    30→    );
    31→
    32→    this.participant.iconPath = new vscode.ThemeIcon('symbol-numeric');
