   157→  private async handlePin(
   158→    request: vscode.ChatRequest,
   159→    stream: vscode.ChatResponseStream,
   160→  ): Promise<vscode.ChatResult> {
   161→    const promptValue = this.stripQuotes(request.prompt.trim());
   162→    let targets: vscode.Uri[] = [];
   163→
   164→    if (!promptValue) {
   165→      const activeUri = vscode.window.activeTextEditor?.document.uri;
   166→      if (!activeUri) {
   167→        stream.markdown('Specify a file to pin or focus the file you want to pin. Example: `@tokalator /pin src/auth.ts`\n');
   168→        return {};
   169→      }
   170→      targets = [activeUri];
   171→    } else {
   172→      targets = await this.resolveUrisFromInput(promptValue);
   173→      if (targets.length === 0) {
   174→        stream.markdown(`No file found matching \`${promptValue}\`\n`);
   175→        return {};
   176→      }
   177→    }
   178→
   179→    const uniqueTargets = this.dedupeUris(targets);
   180→    const pinnedLabels = new Set<string>();
   181→
   182→    for (const uri of uniqueTargets) {
   183→      this.monitor.pinFile(uri.toString());
   184→      pinnedLabels.add(vscode.workspace.asRelativePath(uri, false));
   185→    }
   186→
   187→    const header = pinnedLabels.size === 1 ? 'Pinned file:' : 'Pinned files:';
   188→    const list = Array.from(pinnedLabels)
   189→      .map(label => `- \`${label}\``)
   190→      .join('\n');
   191→
   192→    stream.markdown(`${header}\n${list}\n\nPinned files stay at max relevance and won't be closed by optimize.\n`);
   193→    return {};
   194→  }
