   261→
   262→    stream.markdown(`## 🔮 Next Turn Preview\n\n`);
   263→
   264→    // Current state
   265→    const barLen = 20;
   266→    const currentFilled = Math.round(((preview.currentInput / preview.windowCapacity) * 100 / 100) * barLen);
   267→    const nextFilled = Math.round((preview.percentAfterTurn / 100) * barLen);
   268→    const currentBar = '█'.repeat(currentFilled) + '░'.repeat(barLen - currentFilled);
   269→    const nextBar = '█'.repeat(nextFilled) + '░'.repeat(barLen - nextFilled);
   270→
   271→    stream.markdown(`| | Tokens | Window |\n|---|---|---|\n`);
   272→    stream.markdown(`| **Now** | ~${this.fmtTokens(preview.currentInput)} | \`${currentBar}\` |\n`);
   273→    stream.markdown(`| **After next turn** | ~${this.fmtTokens(preview.nextTurnEstimate)} | \`${nextBar}\` |\n`);
   274→    stream.markdown(`| **Growth** | +~${this.fmtTokens(preview.conversationGrowth)} | |\n`);
   275→    stream.markdown(`| **Output reserve** | ~${this.fmtTokens(preview.outputReserved)} | |\n`);
   276→    stream.markdown(`| **Remaining** | ~${this.fmtTokens(preview.remainingCapacity)} | |\n\n`);
   277→
   278→    // If user typed extra text, count those tokens too
   279→    const userText = request.prompt.trim();
   280→    if (userText) {
   281→      const tokenizer = this.monitor.getTokenizer();
   282→      const textTokens = tokenizer.countTokens(userText, model.provider);
